BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
WITH inventory AS (
 SELECT c.oid,c.relname AS name,c.relrowsecurity AS rls,c.relforcerowsecurity AS force_rls,
 c.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user) AS owned
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE n.nspname='public' AND c.relkind IN('r','p')
 AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.objid=c.oid AND d.deptype='e')
), checked AS (
 SELECT i.name,i.rls,i.force_rls,i.owned,i.name=ANY(ARRAY['law_firm_tenants','signup_intents','platform_admins','global_platform_masters','schema_migrations','holidays_date','subscription_plans','users','cases','case_users','casedescriptions','casetypes','casetypedescriptions','uploadedfiles','stage_files','signingfiles','signaturespots','signing_consents','signing_otp_challenges','signing_file_reminders','signing_signer_delivery','signing_retention_warnings','signing_short_links','audit_events','calendar_events','calendar_event_clients','calendar_event_managers','user_calendar_tokens','user_daily_agenda_settings','otps','refresh_tokens','userdevices','usernotifications','birthday_greetings_sent','chatbot_sessions','chatbot_messages','scheduled_email_reminders','reminder_templates','template_attachments','knowledge_documents','knowledge_chunks','platform_settings','notification_channel_config','email_templates','firm_billing','firm_payment_methods','firm_payment_intents','firm_payment_events','central_system_message_consents','central_system_message_outbox','tenant_subscriptions','data_retention_runs','message_delivery_events','public_short_links','firm_staff_roles','office_integrations','integration_signup_sessions','court_case_links','court_updates','case_whatsapp_groups','whatsapp_contact_permissions','whatsapp_linked_webhook_events','manager_case_activity','manager_platform_activity','signing_templates','signing_batches','signing_batch_files','signing_batch_recipients','signing_batch_sessions','signing_package_completions','signing_batch_reminders','signing_owner_contexts','signing_people','signing_parties','signing_artifacts','signing_authorities','signing_template_versions','signing_submissions','signing_packages','signing_package_assignments','signing_package_revisions','signing_participations','signing_documents','signing_tasks','signing_delivery_profiles','signing_public_grants','signing_grant_items','signing_sessions_v2','signing_actions','signing_approvals','signing_operations','signing_jobs','signing_job_dependencies','signing_deliveries','signing_events_v2','signing_selections','signing_selection_items','signing_otp_challenges_v2','signing_preflights','signing_task_issues','signing_bulk_reviews','signing_replacement_drafts','signing_approval_requests','signing_bulk_requests','signing_delivery_items','signing_creation_drafts','signing_error_alerts','signing_error_emails','signing_selection_snapshots','signing_word_sources','signing_word_source_versions','signing_word_previews','signing_word_authoring_renders','signing_case_stage_rules','signing_case_stage_runs']::text[]) AS classified,
 EXISTS(SELECT 1 FROM pg_policies p WHERE p.schemaname='public' AND p.tablename=i.name AND p.policyname='office_boundary' AND p.permissive='RESTRICTIVE') AS restrictive_office_boundary,
 has_table_privilege(current_user,i.oid,'SELECT') AS can_select,has_table_privilege(current_user,i.oid,'INSERT') AS can_insert,
 has_table_privilege(current_user,i.oid,'UPDATE') AS can_update,has_table_privilege(current_user,i.oid,'DELETE') AS can_delete FROM inventory i
)
SELECT json_build_object(
 'identity',json_build_object('role',current_user,'database',current_database(),'readOnly',current_setting('transaction_read_only')),
 'role',(SELECT row_to_json(x) FROM(SELECT rolsuper AS superuser,rolbypassrls AS bypass_rls,rolcanlogin AS can_login FROM pg_roles WHERE rolname=current_user)x),
 'schemaPrivileges',json_build_object('publicUsage',has_schema_privilege(current_user,'public','USAGE'),'databaseConnect',has_database_privilege(current_user,current_database(),'CONNECT')),
 'inventory',(SELECT coalesce(json_agg(x ORDER BY x.name),'[]'::json) FROM checked x),
 'startupColumns',(SELECT coalesce(json_agg(x),'[]'::json) FROM(SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' AND ((table_name='signaturespots' AND column_name IN('fieldtype','fieldvalue')) OR (table_name='platform_settings' AND column_name IN('category','setting_key','setting_value')) OR (table_name='users' AND column_name='client_profile')))x),
 'sequences',(SELECT coalesce(json_agg(x),'[]'::json) FROM(SELECT c.relname AS name,has_sequence_privilege(current_user,c.oid,'USAGE') AS can_use,has_sequence_privilege(current_user,c.oid,'SELECT') AS can_select,has_sequence_privilege(current_user,c.oid,'UPDATE') AS can_update FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='S' ORDER BY c.relname)x),
 'guardFunctions',(SELECT coalesce(json_agg(x),'[]'::json) FROM(SELECT p.proname AS name,p.prosecdef AS security_definer,p.provolatile AS volatility,has_function_privilege(current_user,p.oid,'EXECUTE') AS can_execute,pg_get_functiondef(p.oid) AS definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('office_row_allowed','guard_office_owner') AND p.prokind IN('f','p'))x),
 'profileAndWordConstraints',(SELECT coalesce(json_agg(x),'[]'::json) FROM(SELECT c.conname AS name,r.relname AS table_name,pg_get_constraintdef(c.oid) AS definition FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='public' AND ((r.relname='users' AND c.conname='users_client_profile_bounded_object') OR r.relname='signing_word_authoring_renders'))x)
);
ROLLBACK;
